"use client";

import * as React from "react";
import * as TabsPrimitive from "@radix-ui/react-tabs";
import gsap from "gsap";
import { useGSAP } from "@gsap/react";
import { cn } from "@/lib/utils";
import { useReducedMotion } from "@/registry/default/lib/use-reduced-motion";

export interface SlideTabsProps {
  items: { value: string; label: string; content: React.ReactNode }[];
  defaultValue?: string;
  className?: string;
}

export function SlideTabs({ items, defaultValue, className }: SlideTabsProps) {
  const [value, setValue] = React.useState(
    defaultValue ?? items[0]?.value ?? ""
  );
  const rootRef = React.useRef<HTMLDivElement>(null);
  const listRef = React.useRef<HTMLDivElement>(null);
  const indicatorRef = React.useRef<HTMLSpanElement>(null);
  const prevIndex = React.useRef(items.findIndex((i) => i.value === value));
  const dirRef = React.useRef(1);
  const reduced = useReducedMotion();

  const moveIndicator = React.useCallback(
    (animate: boolean) => {
      const list = listRef.current;
      const indicator = indicatorRef.current;
      if (!list || !indicator) return;
      const active = list.querySelector<HTMLElement>(
        '[data-state="active"][data-slot="slide-tabs-trigger"]'
      );
      if (!active) return;
      gsap.to(indicator, {
        x: active.offsetLeft,
        width: active.offsetWidth,
        duration: animate && !reduced ? 0.4 : 0,
        ease: "power3.out",
        opacity: 1,
      });
    },
    [reduced]
  );

  // Indicator position: on mount (no animation) + on tab change + on resize.
  useGSAP(
    () => {
      moveIndicator(false);
      const list = listRef.current;
      if (!list) return;
      const ro = new ResizeObserver(() => moveIndicator(false));
      ro.observe(list);
      return () => ro.disconnect();
    },
    { scope: rootRef }
  );

  useGSAP(
    () => {
      moveIndicator(true);
      // Directional content entrance.
      const root = rootRef.current;
      if (!root) return;
      const panel = root.querySelector<HTMLElement>(
        '[data-state="active"][data-slot="slide-tabs-content"]'
      );
      if (!panel) return;
      if (reduced) {
        gsap.set(panel, { opacity: 1, x: 0 });
        return;
      }
      gsap.fromTo(
        panel,
        { opacity: 0, x: dirRef.current * 16 },
        { opacity: 1, x: 0, duration: 0.3, ease: "power2.out" }
      );
    },
    { dependencies: [value], scope: rootRef }
  );

  return (
    <TabsPrimitive.Root
      ref={rootRef}
      data-slot="slide-tabs"
      value={value}
      onValueChange={(next) => {
        const nextIndex = items.findIndex((i) => i.value === next);
        dirRef.current = nextIndex > prevIndex.current ? 1 : -1;
        prevIndex.current = nextIndex;
        setValue(next);
      }}
      className={cn("w-full", className)}
    >
      <TabsPrimitive.List
        ref={listRef}
        data-slot="slide-tabs-list"
        className="relative inline-flex items-center rounded-lg bg-muted p-1"
      >
        <span
          ref={indicatorRef}
          data-slot="slide-tabs-indicator"
          aria-hidden="true"
          className="absolute left-0 top-1 h-8 rounded-md bg-background opacity-0 shadow-sm"
        />
        {items.map((item) => (
          <TabsPrimitive.Trigger
            key={item.value}
            value={item.value}
            data-slot="slide-tabs-trigger"
            className={cn(
              "relative z-10 inline-flex h-8 items-center px-3 text-sm font-medium text-muted-foreground",
              "transition-colors duration-200 data-[state=active]:text-foreground",
              "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring rounded-md"
            )}
          >
            {item.label}
          </TabsPrimitive.Trigger>
        ))}
      </TabsPrimitive.List>
      {items.map((item) => (
        <TabsPrimitive.Content
          key={item.value}
          value={item.value}
          data-slot="slide-tabs-content"
          className="mt-4 focus-visible:outline-none"
        >
          {item.content}
        </TabsPrimitive.Content>
      ))}
    </TabsPrimitive.Root>
  );
}

registry/default/ui/navbar.tsx:
"use client";

import * as React from "react";
import gsap from "gsap";
import { useGSAP } from "@gsap/react";
import { motion } from "motion/react";
import { cn } from "@/lib/utils";
import { useReducedMotion } from "@/registry/default/lib/use-reduced-motion";

export interface NavbarLink {
  href: string;
  label: string;
}

export interface NavbarProps extends React.HTMLAttributes<HTMLElement> {
  links: NavbarLink[];
  activeHref?: string;
  logo?: React.ReactNode;
  cta?: React.ReactNode;
  ref?: React.Ref<HTMLElement>;
}

const springStandard = { type: "spring", stiffness: 380, damping: 32 } as const;

export function Navbar({
  links,
  activeHref,
  logo,
  cta,
  className,
  ref,
  ...rest
}: NavbarProps) {
  const [scrolled, setScrolled] = React.useState(false);
  const [menuOpen, setMenuOpen] = React.useState(false);
  const menuRef = React.useRef<HTMLDivElement>(null);
  const reduced = useReducedMotion();

  React.useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 24);
    onScroll();
    window.addEventListener("scroll", onScroll, { passive: true });
    return () => window.removeEventListener("scroll", onScroll);
  }, []);

  // Lock body scroll while the mobile menu is open.
  React.useEffect(() => {
    if (!menuOpen) return;
    const prev = document.body.style.overflow;
    document.body.style.overflow = "hidden";
    const onKey = (e: KeyboardEvent) => {
      if (e.key === "Escape") setMenuOpen(false);
    };
    window.addEventListener("keydown", onKey);
    return () => {
      document.body.style.overflow = prev;
      window.removeEventListener("keydown", onKey);
    };
  }, [menuOpen]);

  // Mobile menu links cascade rise-in.
  useGSAP(
    () => {
      const menu = menuRef.current;
      if (!menu || !menuOpen) return;
      const items = gsap.utils.toArray<HTMLElement>(
        menu.querySelectorAll('[data-slot="navbar-mobile-link"]')
      );
      if (reduced) {
        gsap.set(items, { y: 0, opacity: 1 });
        return;
      }
      gsap.fromTo(
        items,
        { y: 12, opacity: 0 },
        {
          y: 0,
          opacity: 1,
          duration: 0.35,
          ease: "power2.out",
          stagger: 0.06,
        }
      );
    },
    { dependencies: [menuOpen, reduced], scope: menuRef }
  );

  return (
    <header
      ref={ref}
      data-slot="navbar"
      data-scrolled={scrolled || undefined}
      className={cn(
        "sticky top-0 z-40 w-full transition-[background-color,border-color,backdrop-filter] duration-300",
        scrolled || menuOpen
          ? "border-b border-border bg-background/80 backdrop-blur"
          : "border-b border-transparent bg-transparent",
        className
      )}
      {...rest}
    >
      <nav className="mx-auto flex h-14 max-w-5xl items-center justify-between gap-4 px-4">
        <div data-slot="navbar-logo" className="flex items-center gap-2">
          {logo}
        </div>
        <div className="hidden items-center gap-1 md:flex">
          {links.map((link) => {
            const active = link.href === activeHref;
            return (
              <a
                key={link.href}
                href={link.href}
                data-slot="navbar-link"
                aria-current={active ? "page" : undefined}
                className={cn(
                  "relative rounded-md px-3 py-1.5 text-sm font-medium transition-colors duration-200",
                  active
                    ? "text-foreground"
                    : "text-muted-foreground hover:text-foreground",
                  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
                )}
              >
                {link.label}
                {active ? (
                  <motion.span
                    layoutId="nav-underline"
                    data-slot="navbar-underline"
                    aria-hidden="true"
                    className="absolute inset-x-2 -bottom-px h-0.5 rounded-full bg-foreground"
                    transition={reduced ? { duration: 0 } : springStandard}
                  />
                ) : null}
              </a>
            );
          })}
        </div>
        <div className="flex items-center gap-2">
          {cta}
          <button
            type="button"
            aria-label={menuOpen ? "Close menu" : "Open menu"}
            aria-expanded={menuOpen}
            onClick={() => setMenuOpen((o) => !o)}
            className="relative flex size-9 items-center justify-center rounded-md transition-colors duration-200 hover:bg-muted focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring md:hidden"
          >
            {/* hamburger morphs to X: two bars rotate ±45° */}
            <span
              aria-hidden="true"
              className={cn(
                "absolute h-[1.5px] w-[18px] rounded-full bg-foreground transition-transform duration-[250ms]",
                menuOpen ? "rotate-45" : "-translate-y-[3.5px]"
              )}
            />
            <span
              aria-hidden="true"
              className={cn(
                "absolute h-[1.5px] w-[18px] rounded-full bg-foreground transition-transform duration-[250ms]",
                menuOpen ? "-rotate-45" : "translate-y-[3.5px]"
              )}
            />
          </button>
        </div>
      </nav>
      {menuOpen ? (
        <div
          ref={menuRef}
          data-slot="navbar-mobile-menu"
          className="fixed inset-x-0 bottom-0 top-14 z-40 flex flex-col gap-1 bg-background px-6 py-8 md:hidden"
        >
          {links.map((link) => (
            <a
              key={link.href}
              href={link.href}
              data-slot="navbar-mobile-link"
              aria-current={link.href === activeHref ? "page" : undefined}
              onClick={() => setMenuOpen(false)}
              className={cn(
                "rounded-lg px-3 py-3 text-lg font-medium opacity-0 transition-colors duration-200",
                link.href === activeHref
                  ? "text-foreground"
                  : "text-muted-foreground hover:text-foreground",
                "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
              )}
            >
              {link.label}
            </a>
          ))}
        </div>
      ) : null}
    </header>
  );
}

registry/default/ui/reveal-accordion.tsx:
"use client";

import * as React from "react";
import * as AccordionPrimitive from "@radix-ui/react-accordion";
import { motion } from "motion/react";
import { cn } from "@/lib/utils";
import { useReducedMotion } from "@/registry/default/lib/use-reduced-motion";

export interface RevealAccordionProps {
  items: { value: string; question: string; answer: React.ReactNode }[];
  type?: "single" | "multiple";
  className?: string;
}

const spring = { type: "spring", stiffness: 320, damping: 34 } as const;

export function RevealAccordion({
  items,
  type = "single",
  className,
}: RevealAccordionProps) {
  const [open, setOpen] = React.useState<string[]>([]);
  const reduced = useReducedMotion();
  const transition = reduced ? ({ duration: 0 } as const) : spring;

  const rootProps =
    type === "single"
      ? ({
          type: "single" as const,
          collapsible: true,
          value: open[0] ?? "",
          onValueChange: (v: string) => setOpen(v ? [v] : []),
        } as const)
      : ({
          type: "multiple" as const,
          value: open,
          onValueChange: (v: string[]) => setOpen(v),
        } as const);

  return (
    <AccordionPrimitive.Root
      data-slot="reveal-accordion"
      className={cn("w-full", className)}
      {...rootProps}
    >
      {items.map((item) => {
        const isOpen = open.includes(item.value);
        return (
          <AccordionPrimitive.Item
            key={item.value}
            value={item.value}
            data-slot="reveal-accordion-item"
            className="border-b border-border"
          >
            <AccordionPrimitive.Header asChild>
              <h3 className="flex">
                <AccordionPrimitive.Trigger
                  data-slot="reveal-accordion-trigger"
                  className={cn(
                    "flex w-full items-center justify-between gap-4 py-4 text-left text-sm font-medium text-foreground",
                    "transition-colors duration-200 hover:text-foreground/80",
                    "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring rounded-md"
                  )}
                >
                  {item.question}
                  {/* plus made of two bars; vertical bar rotates 90° => minus */}
                  <span
                    aria-hidden="true"
                    className="relative flex size-4 shrink-0 items-center justify-center"
                  >
                    <span className="absolute h-[1.5px] w-3 rounded-full bg-foreground" />
                    <motion.span
                      className="absolute h-[1.5px] w-3 rounded-full bg-foreground"
                      initial={false}
                      animate={{ rotate: isOpen ? 0 : 90 }}
                      transition={transition}
                    />
                  </span>
                </AccordionPrimitive.Trigger>
              </h3>
            </AccordionPrimitive.Header>
            <AccordionPrimitive.Content forceMount asChild>
              <motion.div
                data-slot="reveal-accordion-content"
                className="overflow-hidden"
                initial={false}
                animate={{
                  height: isOpen ? "auto" : 0,
                  opacity: isOpen ? 1 : 0,
                }}
                transition={transition}
                aria-hidden={!isOpen}
              >
                <div className="pb-4 text-sm leading-6 text-muted-foreground">
                  {item.answer}
                </div>
              </motion.div>
            </AccordionPrimitive.Content>
          </AccordionPrimitive.Item>
        );
      })}
    </AccordionPrimitive.Root>
  );
}

