"use client";

import * as React from "react";
import gsap from "gsap";
import { useGSAP } from "@gsap/react";
import { cn } from "@/lib/utils";
import { useControllableState } from "@/registry/default/lib/use-controllable-state";
import { useReducedMotion } from "@/registry/default/lib/use-reduced-motion";

export interface Skill {
  id: string;
  name: string;
  description?: string;
  icon?: React.ReactNode;
}

export interface SkillsCardProps
  extends React.HTMLAttributes<HTMLDivElement> {
  title: string;
  skills: Skill[];
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  ref?: React.Ref<HTMLDivElement>;
}

export function SkillsCard({
  title,
  skills,
  defaultOpen = false,
  onOpenChange,
  className,
  ref,
  ...rest
}: SkillsCardProps) {
  const [open, setOpen] = useControllableState<boolean>({
    defaultValue: defaultOpen,
    onChange: onOpenChange,
  });
  const rootRef = React.useRef<HTMLDivElement>(null);
  const contentRef = React.useRef<HTMLDivElement>(null);
  const chevronRef = React.useRef<SVGSVGElement>(null);
  const tlRef = React.useRef<gsap.core.Timeline | null>(null);
  const mounted = React.useRef(false);
  const reduced = useReducedMotion();
  const contentId = React.useId();
  React.useImperativeHandle(ref, () => rootRef.current as HTMLDivElement);

  useGSAP(
    () => {
      const content = contentRef.current;
      const chevron = chevronRef.current;
      if (!content || !chevron) return;
      const rows = gsap.utils.toArray<HTMLElement>(
        content.querySelectorAll('[data-slot="skill-row"]')
      );

      // Initial state without animation.
      if (!mounted.current) {
        mounted.current = true;
        gsap.set(content, { height: open ? "auto" : 0 });
        gsap.set(rows, { opacity: open ? 1 : 0, y: open ? 0 : 12 });
        gsap.set(chevron, { rotate: open ? 180 : 0 });
        return;
      }

      // Kill any in-flight timeline and start from current values.
      tlRef.current?.kill();

      if (reduced) {
        gsap.set(content, { height: open ? "auto" : 0 });
        gsap.set(rows, { opacity: open ? 1 : 0, y: 0 });
        gsap.set(chevron, { rotate: open ? 180 : 0 });
        return;
      }

      const tl = gsap.timeline();
      tlRef.current = tl;

      if (open) {
        const h = content.scrollHeight;
        tl.fromTo(
          content,
          { height: content.offsetHeight },
          {
            height: h,
            duration: 0.45,
            ease: "power3.inOut",
            onComplete: () => gsap.set(content, { height: "auto" }),
          }
        );
        tl.fromTo(
          rows,
          { y: 12, opacity: 0 },
          {
            y: 0,
            opacity: 1,
            duration: 0.35,
            ease: "power2.out",
            stagger: 0.05,
          },
          0.12
        );
        tl.to(chevron, { rotate: 180, duration: 0.3, ease: "power2.inOut" }, 0);
      } else {
        tl.to(rows, {
          y: 8,
          opacity: 0,
          duration: 0.2,
          ease: "power2.in",
          stagger: { each: 0.03, from: "end" },
        });
        tl.fromTo(
          content,
          { height: content.offsetHeight },
          { height: 0, duration: 0.32, ease: "power3.inOut" },
          0
        );
        tl.to(chevron, { rotate: 0, duration: 0.3, ease: "power2.inOut" }, 0);
      }
    },
    { dependencies: [open, reduced], scope: rootRef }
  );

  return (
    <div
      ref={rootRef}
      data-slot="skills-card"
      className={cn(
        "w-full max-w-md rounded-xl border border-border bg-card",
        className
      )}
      {...rest}
    >
      <button
        type="button"
        data-slot="header"
        aria-expanded={open}
        aria-controls={contentId}
        onClick={() => setOpen(!open)}
        className={cn(
          "flex w-full items-center justify-between gap-3 rounded-xl px-5 py-4 text-left",
          "transition-colors duration-200 hover:bg-muted/50",
          "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 ring-offset-background"
        )}
      >
        <span className="flex items-baseline gap-2">
          <span className="text-sm font-medium text-foreground">{title}</span>
          <span className="text-xs text-muted-foreground tabular-nums">
            {skills.length}
          </span>
        </span>
        <svg
          ref={chevronRef}
          viewBox="0 0 24 24"
          fill="none"
          stroke="currentColor"
          strokeWidth={2}
          strokeLinecap="round"
          strokeLinejoin="round"
          aria-hidden="true"
          className="size-4 shrink-0 text-muted-foreground"
        >
          <path d="M6 9l6 6 6-6" />
        </svg>
      </button>
      <div
        ref={contentRef}
        id={contentId}
        role="region"
        data-slot="content"
        className="overflow-hidden"
        style={{ height: defaultOpen ? "auto" : 0 }}
      >
        <div className="px-5 pb-4">
          {skills.map((skill, i) => (
            <div
              key={skill.id}
              data-slot="skill-row"
              className={cn(
                "flex items-start gap-3 py-2.5",
                i > 0 && "border-t border-border"
              )}
            >
              <span className="mt-0.5 flex size-5 shrink-0 items-center justify-center text-muted-foreground [&>svg]:size-4">
                {skill.icon ?? (
                  <svg
                    viewBox="0 0 24 24"
                    fill="none"
                    stroke="currentColor"
                    strokeWidth={2}
                    strokeLinecap="round"
                    strokeLinejoin="round"
                    aria-hidden="true"
                  >
                    <path d="M12 2l2.4 7.2H22l-6 4.8 2.4 7.2-6.4-4.8L5.6 21.2 8 14 2 9.2h7.6L12 2z" />
                  </svg>
                )}
              </span>
              <span className="min-w-0">
                <span className="block text-sm font-medium text-foreground">
                  {skill.name}
                </span>
                {skill.description ? (
                  <span className="block text-xs text-muted-foreground">
                    {skill.description}
                  </span>
                ) : null}
              </span>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

"use client";

import * as React from "react";
import gsap from "gsap";
import { ScrollTrigger } from "gsap/ScrollTrigger";
import { useGSAP } from "@gsap/react";
import { cn } from "@/lib/utils";
import { useReducedMotion } from "@/registry/default/lib/use-reduced-motion";

gsap.registerPlugin(ScrollTrigger);

export interface KineticHeadingProps
  extends React.HTMLAttributes<HTMLHeadingElement> {
  text: string;
  as?: "h1" | "h2" | "h3";
  trigger?: "mount" | "scroll";
  /** Seconds per char. Default 0.028. */
  stagger?: number;
  delay?: number;
  ref?: React.Ref<HTMLHeadingElement>;
}

const SIZE: Record<string, string> = {
  h1: "text-4xl md:text-6xl",
  h2: "text-3xl md:text-5xl",
  h3: "text-2xl md:text-4xl",
};

export function KineticHeading({
  text,
  as = "h1",
  trigger = "mount",
  stagger = 0.028,
  delay = 0,
  className,
  ref,
  ...rest
}: KineticHeadingProps) {
  const rootRef = React.useRef<HTMLHeadingElement>(null);
  const reduced = useReducedMotion();
  const Tag = as;
  React.useImperativeHandle(ref, () => rootRef.current as HTMLHeadingElement);

  const words = React.useMemo(() => text.split(" "), [text]);

  useGSAP(
    () => {
      const root = rootRef.current;
      if (!root) return;
      const chars = gsap.utils.toArray<HTMLElement>(
        root.querySelectorAll('[data-slot="char"]')
      );

      if (reduced) {
        gsap.set(root, { visibility: "visible" });
        gsap.set(chars, { yPercent: 0, opacity: 1 });
        return;
      }

      gsap.set(chars, { yPercent: 110, opacity: 0 });
      gsap.set(root, { visibility: "visible" });

      const vars: gsap.TweenVars = {
        yPercent: 0,
        opacity: 1,
        duration: 0.9,
        ease: "power4.out",
        stagger,
        delay,
      };
      if (trigger === "scroll") {
        vars.scrollTrigger = { trigger: root, start: "top 85%", once: true };
      }
      gsap.to(chars, vars);
    },
    { dependencies: [text, trigger, stagger, delay, reduced], scope: rootRef }
  );

  return (
    <Tag
      ref={rootRef}
      data-slot="kinetic-heading"
      aria-label={text}
      style={{ visibility: "hidden" }}
      className={cn(
        "font-semibold tracking-tight text-foreground",
        SIZE[as],
        className
      )}
      {...rest}
    >
      {words.map((word, wi) => (
        <React.Fragment key={wi}>
          <span
            data-slot="word"
            aria-hidden="true"
            className="inline-block overflow-hidden align-bottom"
          >
            {Array.from(word).map((char, ci) => (
              <span key={ci} data-slot="char" className="inline-block">
                {char}
              </span>
            ))}
          </span>
          {wi < words.length - 1 ? " " : null}
        </React.Fragment>
      ))}
    </Tag>
  );
}

"use client";

import * as React from "react";
import gsap from "gsap";
import { useGSAP } from "@gsap/react";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "@/lib/utils";
import { useReducedMotion } from "@/registry/default/lib/use-reduced-motion";

const magneticButtonVariants = cva(
  [
    "inline-flex items-center justify-center rounded-full font-medium select-none",
    "transition-colors duration-200",
    "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 ring-offset-background",
    "disabled:opacity-50 disabled:pointer-events-none",
  ].join(" "),
  {
    variants: {
      variant: {
        default: "bg-primary text-primary-foreground hover:bg-primary/90",
        outline: "border border-input bg-background hover:bg-muted",
        ghost: "hover:bg-muted",
      },
      size: {
        default: "h-11 px-6 text-sm",
        lg: "h-13 px-8 text-base",
      },
    },
    defaultVariants: { variant: "default", size: "default" },
  }
);

export interface MagneticButtonProps
  extends React.ButtonHTMLAttributes<HTMLButtonElement>,
    VariantProps<typeof magneticButtonVariants> {
  /** Fraction of cursor offset applied (0–1). Default 0.35. */
  strength?: number;
  /** Activation distance from center in px. Default 120. */
  radius?: number;
  ref?: React.Ref<HTMLButtonElement>;
}

export function MagneticButton({
  strength = 0.35,
  radius = 120,
  variant,
  size,
  className,
  children,
  ref,
  ...rest
}: MagneticButtonProps) {
  const wrapperRef = React.useRef<HTMLSpanElement>(null);
  const buttonRef = React.useRef<HTMLButtonElement>(null);
  const labelRef = React.useRef<HTMLSpanElement>(null);
  const reduced = useReducedMotion();
  React.useImperativeHandle(ref, () => buttonRef.current as HTMLButtonElement);

  useGSAP(
    () => {
      const button = buttonRef.current;
      const label = labelRef.current;
      const wrapper = wrapperRef.current;
      if (!button || !label || !wrapper) return;
      if (reduced) return;
      // Disabled on touch devices — behaves as a normal button.
      if (window.matchMedia("(pointer: coarse)").matches) return;

      const xTo = gsap.quickTo(button, "x", { duration: 0.6, ease: "power3" });
      const yTo = gsap.quickTo(button, "y", { duration: 0.6, ease: "power3" });
      const lxTo = gsap.quickTo(label, "x", { duration: 0.6, ease: "power3" });
      const lyTo = gsap.quickTo(label, "y", { duration: 0.6, ease: "power3" });

      const onMove = (e: PointerEvent) => {
        const rect = button.getBoundingClientRect();
        const cx = rect.left + rect.width / 2;
        const cy = rect.top + rect.height / 2;
        const dx = e.clientX - cx;
        const dy = e.clientY - cy;
        if (Math.hypot(dx, dy) < radius) {
          xTo(dx * strength);
          yTo(dy * strength);
          lxTo(dx * strength * 0.5);
          lyTo(dy * strength * 0.5);
        } else {
          xTo(0);
          yTo(0);
          lxTo(0);
          lyTo(0);
        }
      };

      const onLeave = () => {
        gsap.to([button, label], {
          x: 0,
          y: 0,
          duration: 0.7,
          ease: "elastic.out(1, 0.45)",
        });
      };

      window.addEventListener("pointermove", onMove, { passive: true });
      wrapper.addEventListener("pointerleave", onLeave);
      return () => {
        window.removeEventListener("pointermove", onMove);
        wrapper.removeEventListener("pointerleave", onLeave);
      };
    },
    { dependencies: [strength, radius, reduced], scope: wrapperRef }
  );

  return (
    <span
      ref={wrapperRef}
      data-slot="magnetic-wrapper"
      className="inline-block p-3"
    >
      <button
        ref={buttonRef}
        data-slot="magnetic-button"
        className={cn(magneticButtonVariants({ variant, size }), className)}
        {...rest}
      >
        <span ref={labelRef} data-slot="label" className="inline-block">
          {children}
        </span>
      </button>
    </span>
  );
}

registry/default/motion/marquee.tsx:
"use client";

import * as React from "react";
import gsap from "gsap";
import { useGSAP } from "@gsap/react";
import { cn } from "@/lib/utils";
import { useReducedMotion } from "@/registry/default/lib/use-reduced-motion";

export interface MarqueeProps extends React.HTMLAttributes<HTMLDivElement> {
  /** Seconds per loop. Default 30. */
  speed?: number;
  direction?: "left" | "right";
  ref?: React.Ref<HTMLDivElement>;
}

export function Marquee({
  speed = 30,
  direction = "left",
  className,
  children,
  ref,
  ...rest
}: MarqueeProps) {
  const rootRef = React.useRef<HTMLDivElement>(null);
  const trackRef = React.useRef<HTMLDivElement>(null);
  const tweenRef = React.useRef<gsap.core.Tween | null>(null);
  const reduced = useReducedMotion();
  React.useImperativeHandle(ref, () => rootRef.current as HTMLDivElement);

  useGSAP(
    () => {
      const track = trackRef.current;
      if (!track || reduced) return;
      tweenRef.current = gsap.to(track, {
        xPercent: direction === "left" ? -50 : 50,
        ease: "none",
        duration: speed,
        repeat: -1,
      });
      return () => {
        tweenRef.current = null;
      };
    },
    { dependencies: [speed, direction, reduced], scope: rootRef }
  );

  // Hover eases the loop to a stop via timeScale (not an abrupt pause).
  const onEnter = () => {
    if (tweenRef.current) {
      gsap.to(tweenRef.current, { timeScale: 0, duration: 0.4 });
    }
  };
  const onLeave = () => {
    if (tweenRef.current) {
      gsap.to(tweenRef.current, { timeScale: 1, duration: 0.4 });
    }
  };

  return (
    <div
      ref={rootRef}
      data-slot="marquee"
      onPointerEnter={onEnter}
      onPointerLeave={onLeave}
      className={cn(
        "w-full overflow-hidden",
        "[mask-image:linear-gradient(to_right,transparent,black_10%,black_90%,transparent)]",
        className
      )}
      {...rest}
    >
      <div
        ref={trackRef}
        data-slot="track"
        className="flex w-max items-center gap-12 pr-12"
      >
        {/* duplicated 2x for a seamless -50% loop */}
        <div aria-hidden={false} className="flex shrink-0 items-center gap-12">
          {children}
        </div>
        <div aria-hidden="true" className="flex shrink-0 items-center gap-12">
          {children}
        </div>
      </div>
    </div>
  );
}

registry/default/motion/text-roll-link.t:
"use client";

import * as React from "react";
import gsap from "gsap";
import { useGSAP } from "@gsap/react";
import { cn } from "@/lib/utils";
import { useReducedMotion } from "@/registry/default/lib/use-reduced-motion";

export interface TextRollLinkProps
  extends React.AnchorHTMLAttributes<HTMLAnchorElement> {
  label: string;
  ref?: React.Ref<HTMLAnchorElement>;
}

export function TextRollLink({
  label,
  className,
  ref,
  ...rest
}: TextRollLinkProps) {
  const rootRef = React.useRef<HTMLAnchorElement>(null);
  const underlineRef = React.useRef<HTMLSpanElement>(null);
  const reduced = useReducedMotion();
  React.useImperativeHandle(ref, () => rootRef.current as HTMLAnchorElement);

  const chars = React.useMemo(() => Array.from(label), [label]);

  useGSAP(
    () => {
      const root = rootRef.current;
      const underline = underlineRef.current;
      if (!root || !underline || reduced) return;

      const stacks = gsap.utils.toArray<HTMLElement>(
        root.querySelectorAll('[data-slot="char-stack"]')
      );
      gsap.set(underline, { scaleX: 0, transformOrigin: "left" });

      const enter = () => {
        gsap.to(stacks, {
          yPercent: -100,
          duration: 0.35,
          ease: "power3.inOut",
          stagger: 0.015,
          overwrite: true,
        });
        gsap.to(underline, {
          scaleX: 1,
          transformOrigin: "left",
          duration: 0.3,
          ease: "power3.out",
          overwrite: true,
        });
      };
      const leave = () => {
        gsap.to(stacks, {
          yPercent: 0,
          duration: 0.35,
          ease: "power3.inOut",
          stagger: 0.015,
          overwrite: true,
        });
        gsap.to(underline, {
          scaleX: 0,
          transformOrigin: "right",
          duration: 0.3,
          ease: "power3.out",
          overwrite: true,
        });
      };

      root.addEventListener("pointerenter", enter);
      root.addEventListener("pointerleave", leave);
      root.addEventListener("focus", enter);
      root.addEventListener("blur", leave);
      return () => {
        root.removeEventListener("pointerenter", enter);
        root.removeEventListener("pointerleave", leave);
        root.removeEventListener("focus", enter);
        root.removeEventListener("blur", leave);
      };
    },
    { dependencies: [label, reduced], scope: rootRef }
  );

  return (
    <a
      ref={rootRef}
      data-slot="text-roll-link"
      aria-label={label}
      className={cn(
        "relative inline-block pb-0.5 text-sm font-medium text-foreground",
        "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring rounded-sm",
        className
      )}
      {...rest}
    >
      <span aria-hidden="true" className="flex">
        {chars.map((char, i) => (
          <span
            key={i}
            className="inline-block h-[1.2em] overflow-hidden leading-[1.2em]"
          >
            <span data-slot="char-stack" className="flex flex-col">
              <span className="block whitespace-pre">{char}</span>
              <span className="block whitespace-pre">{char}</span>
            </span>
          </span>
        ))}
      </span>
      <span
        ref={underlineRef}
        data-slot="underline"
        aria-hidden="true"
        className="absolute bottom-0 left-0 h-px w-full bg-foreground"
      />
    </a>
  );
}

