"use client";

import * as React from "react";
import gsap from "gsap";
import { useGSAP } from "@gsap/react";
import { cn } from "@/lib/utils";
import { useReducedMotion } from "@/registry/default/lib/use-reduced-motion";
import { Button } from "@/registry/default/ui/button";
import { Input } from "@/registry/default/ui/input";
import { Field } from "@/registry/default/ui/field";
import { Checkbox } from "@/registry/default/ui/checkbox";
import { Alert } from "@/registry/default/ui/alert";

export interface LoginCardProps
  extends Omit<React.HTMLAttributes<HTMLDivElement>, "onSubmit" | "title"> {
  onSubmit: (data: {
    email: string;
    password: string;
    remember: boolean;
  }) => Promise<void>;
  title?: string;
  forgotHref?: string;
  signupHref?: string;
  ref?: React.Ref<HTMLDivElement>;
}

const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

export function LoginCard({
  onSubmit,
  title = "Welcome back",
  forgotHref = "#forgot",
  signupHref,
  className,
  ref,
  ...rest
}: LoginCardProps) {
  const cardRef = React.useRef<HTMLDivElement>(null);
  const bodyRef = React.useRef<HTMLDivElement>(null);
  const prevBodyHeight = React.useRef(0);
  const reduced = useReducedMotion();
  React.useImperativeHandle(ref, () => cardRef.current as HTMLDivElement);

  const [values, setValues] = React.useState({
    email: "",
    password: "",
    remember: false,
  });
  const [errors, setErrors] = React.useState<{
    email?: string;
    password?: string;
  }>({});
  const erred = React.useRef(new Set<"email" | "password">());
  const [loading, setLoading] = React.useState(false);
  const [success, setSuccess] = React.useState(false);
  const [done, setDone] = React.useState(false);
  const [submitError, setSubmitError] = React.useState<string | null>(null);

  const emailRef = React.useRef<HTMLInputElement>(null);
  const passwordRef = React.useRef<HTMLInputElement>(null);

  const validate = (
    field: "email" | "password",
    v = values
  ): string | undefined => {
    if (field === "email")
      return EMAIL_RE.test(v.email)
        ? undefined
        : "Enter a valid email address";
    return v.password.length > 0 ? undefined : "Enter your password";
  };

  const handleBlur = (field: "email" | "password") => {
    const msg = validate(field);
    if (msg) erred.current.add(field);
    setErrors((e) => ({ ...e, [field]: msg }));
  };
  const handleChange = (
    field: "email" | "password",
    next: Partial<typeof values>
  ) => {
    const merged = { ...values, ...next };
    setValues(merged);
    if (erred.current.has(field)) {
      setErrors((e) => ({ ...e, [field]: validate(field, merged) }));
    }
  };

  useGSAP(
    () => {
      const card = cardRef.current;
      if (!card) return;
      const items = gsap.utils.toArray<HTMLElement>(
        card.querySelectorAll('[data-slot="cascade-item"]')
      );
      if (reduced) {
        gsap.set(card, { opacity: 1, scale: 1 });
        gsap.set(items, { opacity: 1, y: 0 });
        return;
      }
      gsap.fromTo(
        card,
        { opacity: 0, scale: 0.96 },
        { opacity: 1, scale: 1, duration: 0.25, ease: "power3.out" }
      );
      gsap.fromTo(
        items,
        { y: 12, opacity: 0 },
        {
          y: 0,
          opacity: 1,
          duration: 0.35,
          ease: "power2.out",
          stagger: 0.05,
          delay: 0.05,
        }
      );
    },
    { scope: cardRef }
  );

  useGSAP(
    () => {
      const body = bodyRef.current;
      if (!body || !done) return;
      const panel = body.querySelector<HTMLElement>(
        '[data-slot="success-panel"]'
      );
      if (!panel) return;
      if (reduced) {
        gsap.set(body, { height: "auto" });
        gsap.set(panel, { opacity: 1 });
        return;
      }
      gsap.fromTo(
        body,
        { height: prevBodyHeight.current },
        {
          height: body.scrollHeight,
          duration: 0.45,
          ease: "power3.inOut",
          onComplete: () => gsap.set(body, { height: "auto" }),
        }
      );
      gsap.fromTo(panel, { opacity: 0 }, { opacity: 1, duration: 0.3 });
      const circle = panel.querySelector<HTMLElement>('[data-slot="circle"]');
      const check = panel.querySelector<SVGPathElement>('[data-slot="check"]');
      const headline = panel.querySelector<HTMLElement>(
        '[data-slot="headline"]'
      );
      if (circle)
        gsap.fromTo(
          circle,
          { scale: 0 },
          { scale: 1, duration: 0.4, ease: "back.out(1.7)", delay: 0.1 }
        );
      if (check)
        gsap.fromTo(
          check,
          { strokeDashoffset: 1 },
          { strokeDashoffset: 0, duration: 0.3, ease: "power2.out", delay: 0.45 }
        );
      if (headline)
        gsap.fromTo(
          headline,
          { y: 12, opacity: 0 },
          { y: 0, opacity: 1, duration: 0.35, ease: "power2.out", delay: 0.25 }
        );
    },
    { dependencies: [done, reduced], scope: cardRef }
  );

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    const nextErrors: typeof errors = {};
    for (const f of ["email", "password"] as const) {
      const msg = validate(f);
      if (msg) {
        nextErrors[f] = msg;
        erred.current.add(f);
      }
    }
    if (Object.keys(nextErrors).length > 0) {
      setErrors(nextErrors);
      if (nextErrors.email) emailRef.current?.focus();
      else passwordRef.current?.focus();
      return;
    }
    setErrors({});
    setSubmitError(null);
    setLoading(true);
    try {
      await onSubmit(values);
      setLoading(false);
      setSuccess(true);
    } catch (err) {
      setLoading(false);
      setSubmitError(
        err instanceof Error ? err.message : "Invalid email or password."
      );
    }
  };

  return (
    <div
      ref={cardRef}
      data-slot="login-card"
      className={cn(
        "w-full max-w-md rounded-2xl border border-border bg-card p-8 opacity-0 shadow-sm",
        className
      )}
      {...rest}
    >
      <div ref={bodyRef} className="overflow-hidden">
        {done ? (
          <div
            data-slot="success-panel"
            className="flex flex-col items-center gap-2 py-6 text-center opacity-0"
          >
            <span
              data-slot="circle"
              className="flex size-12 items-center justify-center rounded-full bg-emerald-600/10"
            >
              <svg
                viewBox="0 0 24 24"
                fill="none"
                stroke="currentColor"
                strokeWidth={2.5}
                strokeLinecap="round"
                strokeLinejoin="round"
                className="size-6 text-emerald-600 dark:text-emerald-400"
                aria-hidden="true"
              >
                <path
                  data-slot="check"
                  d="M5 13l4 4L19 7"
                  pathLength={1}
                  strokeDasharray={1}
                  strokeDashoffset={1}
                />
              </svg>
            </span>
            <h2
              data-slot="headline"
              className="mt-2 text-xl font-semibold text-foreground opacity-0"
            >
              You&apos;re in
            </h2>
          </div>
        ) : (
          <form noValidate onSubmit={handleSubmit} className="flex flex-col">
            <div data-slot="cascade-item">
              <h2 className="text-xl font-semibold text-foreground">{title}</h2>
              <p className="mt-1 text-sm text-muted-foreground">
                Sign in to continue to your account.
              </p>
            </div>

            {submitError != null ? (
              <div className="mt-4">
                <Alert variant="destructive" title={submitError} />
              </div>
            ) : null}

            <div data-slot="cascade-item" className="mt-6">
              <Field
                label="Email"
                state={errors.email ? "error" : null}
                message={errors.email}
              >
                <Input
                  ref={emailRef}
                  type="email"
                  name="email"
                  autoComplete="email"
                  value={values.email}
                  invalid={!!errors.email}
                  onChange={(e) =>
                    handleChange("email", { email: e.currentTarget.value })
                  }
                  onBlur={() => handleBlur("email")}
                  disabled={loading || success}
                />
              </Field>
            </div>

            <div data-slot="cascade-item" className="mt-4">
              <Field
                label={
                  <span className="flex w-full items-center justify-between">
                    Password
                    <a
                      href={forgotHref}
                      tabIndex={0}
                      className="text-xs font-medium text-muted-foreground underline-offset-4 hover:text-foreground hover:underline"
                    >
                      Forgot password?
                    </a>
                  </span>
                }
                state={errors.password ? "error" : null}
                message={errors.password}
              >
                <Input
                  ref={passwordRef}
                  type="password"
                  name="current-password"
                  autoComplete="current-password"
                  value={values.password}
                  invalid={!!errors.password}
                  onChange={(e) =>
                    handleChange("password", {
                      password: e.currentTarget.value,
                    })
                  }
                  onBlur={() => handleBlur("password")}
                  disabled={loading || success}
                />
              </Field>
            </div>

            <div data-slot="cascade-item" className="mt-4">
              <label className="flex items-center gap-2.5 text-sm text-muted-foreground">
                <Checkbox
                  checked={values.remember}
                  onCheckedChange={(c) =>
                    setValues((v) => ({ ...v, remember: c === true }))
                  }
                  disabled={loading || success}
                />
                Remember me
              </label>
            </div>

            <div data-slot="cascade-item" className="mt-6">
              <Button
                type="submit"
                size="lg"
                className="w-full"
                loading={loading}
                success={success}
                onSuccessEnd={() => {
                  prevBodyHeight.current = bodyRef.current?.offsetHeight ?? 0;
                  setSuccess(false);
                  setDone(true);
                }}
              >
                Sign in
              </Button>
            </div>

            {signupHref ? (
              <p
                data-slot="cascade-item"
                className="mt-5 text-center text-sm text-muted-foreground"
              >
                No account?{" "}
                <a
                  href={signupHref}
                  className="font-medium text-foreground underline-offset-4 hover:underline"
                >
                  Create one
                </a>
              </p>
            ) : null}
          </form>
        )}
      </div>
    </div>
  );
}

registry/default/blocks/pricing-card.tsx:
"use client";

import * as React from "react";
import gsap from "gsap";
import { useGSAP } from "@gsap/react";
import { motion, AnimatePresence } from "motion/react";
import { cn } from "@/lib/utils";
import { useReducedMotion } from "@/registry/default/lib/use-reduced-motion";
import { Button } from "@/registry/default/ui/button";
import { Badge } from "@/registry/default/ui/badge";
import { NumberFlow } from "@/registry/default/fintech/number-flow";

export interface PricingCardProps
  extends Omit<React.HTMLAttributes<HTMLDivElement>, "onSelect"> {
  plan: string;
  description?: string;
  monthlyPrice: number;
  yearlyPrice: number;
  currencyPrefix?: string;
  features: string[];
  featured?: boolean;
  ctaLabel?: string;
  savingsLabel?: string;
  onSelect?: (billing: "monthly" | "yearly") => void;
  ref?: React.Ref<HTMLDivElement>;
}

function FeatureCheck({ delay }: { delay: number }) {
  const reduced = useReducedMotion();
  const [drawn, setDrawn] = React.useState(false);
  React.useEffect(() => {
    if (reduced) {
      setDrawn(true);
      return;
    }
    const t = setTimeout(() => setDrawn(true), delay);
    return () => clearTimeout(t);
  }, [delay, reduced]);
  return (
    <svg
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth={2.5}
      strokeLinecap="round"
      strokeLinejoin="round"
      className="mt-0.5 size-3.5 shrink-0 text-emerald-600 dark:text-emerald-400"
      aria-hidden="true"
    >
      <path
        d="M5 13l4 4L19 7"
        pathLength={1}
        strokeDasharray={1}
        strokeDashoffset={drawn ? 0 : 1}
        className="transition-[stroke-dashoffset] duration-300 ease-out"
      />
    </svg>
  );
}

export function PricingCard({
  plan,
  description,
  monthlyPrice,
  yearlyPrice,
  currencyPrefix = "$",
  features,
  featured = false,
  ctaLabel = "Get started",
  savingsLabel = "Save 20%",
  onSelect,
  className,
  ref,
  ...rest
}: PricingCardProps) {
  const [billing, setBilling] = React.useState<"monthly" | "yearly">(
    "monthly"
  );
  const rootRef = React.useRef<HTMLDivElement>(null);
  const reduced = useReducedMotion();
  React.useImperativeHandle(ref, () => rootRef.current as HTMLDivElement);

  const springStandard = {
    type: "spring",
    stiffness: 380,
    damping: 32,
  } as const;

  // Feature rows cascade on mount.
  useGSAP(
    () => {
      const root = rootRef.current;
      if (!root) return;
      const rows = gsap.utils.toArray<HTMLElement>(
        root.querySelectorAll('[data-slot="feature-row"]')
      );
      if (reduced) {
        gsap.set(rows, { y: 0, opacity: 1 });
        return;
      }
      gsap.fromTo(
        rows,
        { y: 12, opacity: 0 },
        {
          y: 0,
          opacity: 1,
          duration: 0.35,
          ease: "power2.out",
          stagger: 0.05,
          delay: 0.1,
        }
      );
    },
    { scope: rootRef }
  );

  const price = billing === "monthly" ? monthlyPrice : yearlyPrice;

  return (
    <div
      ref={rootRef}
      data-slot="pricing-card"
      className={cn(
        "relative w-full max-w-sm rounded-2xl border bg-card p-6 shadow-sm",
        featured ? "border-primary" : "border-border",
        className
      )}
      {...rest}
    >
      {featured ? (
        <div className="absolute -top-3 left-1/2 -translate-x-1/2">
          <Badge>Most popular</Badge>
        </div>
      ) : null}

      <div className="flex items-center justify-between gap-2">
        <h3 className="text-sm font-semibold text-foreground">{plan}</h3>
        {/* billing toggle: two-option sliding pill */}
        <div
          data-slot="billing-toggle"
          role="tablist"
          aria-label="Billing period"
          className="relative inline-flex items-center rounded-lg bg-muted p-0.5"
        >
          {(["monthly", "yearly"] as const).map((b) => (
            <button
              key={b}
              role="tab"
              aria-selected={billing === b}
              onClick={() => {
                setBilling(b);
                onSelect?.(b);
              }}
              className={cn(
                "relative z-10 rounded-md px-2.5 py-1 text-xs font-medium capitalize",
                "transition-colors duration-200",
                billing === b
                  ? "text-foreground"
                  : "text-muted-foreground hover:text-foreground",
                "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
              )}
            >
              {billing === b ? (
                <motion.span
                  layoutId={`billing-pill-${plan}`}
                  aria-hidden="true"
                  className="absolute inset-0 -z-10 rounded-md bg-background shadow-sm"
                  transition={reduced ? { duration: 0 } : springStandard}
                />
              ) : null}
              {b}
            </button>
          ))}
        </div>
      </div>

      {description ? (
        <p className="mt-2 text-sm text-muted-foreground">{description}</p>
      ) : null}

      <div className="mt-5 flex items-baseline gap-2">
        <span className="text-4xl font-semibold tracking-tight text-foreground">
          <NumberFlow value={price} prefix={currencyPrefix} />
        </span>
        <span className="text-sm text-muted-foreground">
          /{billing === "monthly" ? "mo" : "yr"}
        </span>
        <AnimatePresence>
          {billing === "yearly" ? (
            <motion.span
              initial={
                reduced ? { opacity: 0 } : { opacity: 0, scale: 0.96 }
              }
              animate={{ opacity: 1, scale: 1 }}
              exit={{ opacity: 0, scale: 0.96 }}
              transition={
                reduced ? { duration: 0 } : { duration: 0.25, ease: "easeOut" }
              }
            >
              <Badge variant="success">{savingsLabel}</Badge>
            </motion.span>
          ) : null}
        </AnimatePresence>
      </div>

      <ul className="mt-6 flex flex-col gap-2.5">
        {features.map((feature, i) => (
          <li
            key={feature}
            data-slot="feature-row"
            className="flex items-start gap-2.5 text-sm text-foreground opacity-0"
          >
            <FeatureCheck delay={150 + i * 50} />
            {feature}
          </li>
        ))}
      </ul>

      <div className="mt-6">
        <Button
          className="w-full"
          variant={featured ? "default" : "outline"}
          onClick={() => onSelect?.(billing)}
        >
          {ctaLabel}
        </Button>
      </div>
    </div>
  );
}

registry/default/blocks/newsletter-input:
"use client";

import * as React from "react";
import gsap from "gsap";
import { useGSAP } from "@gsap/react";
import { cn } from "@/lib/utils";
import { useReducedMotion } from "@/registry/default/lib/use-reduced-motion";
import { Button } from "@/registry/default/ui/button";
import { FieldMessage } from "@/registry/default/ui/field-message";

export interface NewsletterInputProps
  extends Omit<React.HTMLAttributes<HTMLDivElement>, "onSubmit"> {
  onSubmit: (email: string) => Promise<void> | void;
  placeholder?: string;
  buttonLabel?: string;
  ref?: React.Ref<HTMLDivElement>;
}

const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

type Phase = "idle" | "loading" | "success";

export function NewsletterInput({
  onSubmit,
  placeholder = "you@example.com",
  buttonLabel = "Subscribe",
  className,
  ref,
  ...rest
}: NewsletterInputProps) {
  const rootRef = React.useRef<HTMLDivElement>(null);
  const controlRef = React.useRef<HTMLDivElement>(null);
  const successRef = React.useRef<HTMLSpanElement>(null);
  const inputRef = React.useRef<HTMLInputElement>(null);
  const widthBeforeMorph = React.useRef(0);
  const [email, setEmail] = React.useState("");
  const [phase, setPhase] = React.useState<Phase>("idle");
  const [error, setError] = React.useState<string | null>(null);
  const [drawn, setDrawn] = React.useState(false);
  const reduced = useReducedMotion();
  React.useImperativeHandle(ref, () => rootRef.current as HTMLDivElement);

  const shake = React.useCallback(() => {
    if (reduced || !controlRef.current) return;
    gsap.fromTo(
      controlRef.current,
      { x: 0 },
      {
        x: 0,
        duration: 0.4,
        ease: "none",
        keyframes: { x: [-6, 6, -4, 4, -2, 0] },
      }
    );
  }, [reduced]);

  // Morph the control into the success pill and back.
  useGSAP(
    () => {
      const control = controlRef.current;
      const success = successRef.current;
      if (!control || !success) return;
      if (phase === "success") {
        const target = success.offsetWidth;
        setDrawn(false);
        const t = setTimeout(() => setDrawn(true), 200);
        if (reduced) {
          gsap.set(control, { width: target });
          return () => clearTimeout(t);
        }
        gsap.fromTo(
          control,
          { width: widthBeforeMorph.current },
          { width: target, duration: 0.35, ease: "power3.inOut" }
        );
        return () => clearTimeout(t);
      }
      if (phase === "idle" && widthBeforeMorph.current > 0) {
        if (reduced) {
          gsap.set(control, { width: "auto" });
          return;
        }
        gsap.fromTo(
          control,
          { width: control.offsetWidth },
          {
            width: widthBeforeMorph.current,
            duration: 0.35,
            ease: "power3.inOut",
            onComplete: () => gsap.set(control, { width: "auto" }),
          }
        );
      }
    },
    { dependencies: [phase, reduced], scope: rootRef }
  );

  const submit = async () => {
    if (phase !== "idle") return;
    if (!EMAIL_RE.test(email)) {
      setError("Enter a valid email address");
      shake();
      return;
    }
    setError(null);
    widthBeforeMorph.current = controlRef.current?.offsetWidth ?? 0;
    setPhase("loading");
    try {
      await onSubmit(email);
      setPhase("success");
      setTimeout(() => {
        setEmail("");
        setPhase("idle");
      }, 3000);
    } catch {
      setPhase("idle");
      setError("Something went wrong. Try again.");
      shake();
    }
  };

  return (
    <div
      ref={rootRef}
      data-slot="newsletter-input"
      className={cn("inline-flex flex-col", className)}
      {...rest}
    >
      <div
        ref={controlRef}
        data-slot="control"
        className={cn(
          "relative flex h-12 items-center overflow-hidden rounded-full border border-input bg-background pl-4 pr-1.5",
          "transition-[border-color,box-shadow] duration-200",
          "focus-within:border-ring focus-within:ring-2 focus-within:ring-ring/25",
          error != null && "border-destructive focus-within:ring-destructive/25",
          phase === "success" && "justify-center border-emerald-600 px-0"
        )}
      >
        <div
          className={cn(
            "flex w-full items-center gap-2 transition-opacity duration-200",
            phase === "success" && "pointer-events-none opacity-0"
          )}
        >
          <input
            ref={inputRef}
            type="email"
            inputMode="email"
            autoComplete="email"
            aria-label="Email address"
            aria-invalid={error != null || undefined}
            placeholder={placeholder}
            value={email}
            disabled={phase !== "idle"}
            onChange={(e) => {
              setEmail(e.currentTarget.value);
              if (error != null && EMAIL_RE.test(e.currentTarget.value)) {
                setError(null);
              }
            }}
            onKeyDown={(e) => {
              if (e.key === "Enter") void submit();
            }}
            className="w-52 flex-1 bg-transparent text-sm text-foreground outline-none placeholder:text-muted-foreground"
          />
          <Button
            type="button"
            size="sm"
            className="rounded-full"
            loading={phase === "loading"}
            onClick={() => void submit()}
          >
            {buttonLabel}
          </Button>
        </div>
        <span
          ref={successRef}
          data-slot="success-pill"
          aria-live="polite"
          className={cn(
            "absolute inline-flex items-center gap-2 whitespace-nowrap px-5 text-sm font-medium",
            "text-emerald-600 transition-opacity duration-200 dark:text-emerald-400",
            phase === "success" ? "opacity-100" : "pointer-events-none opacity-0"
          )}
        >
          <svg
            viewBox="0 0 24 24"
            fill="none"
            stroke="currentColor"
            strokeWidth={2.5}
            strokeLinecap="round"
            strokeLinejoin="round"
            className="size-4"
            aria-hidden="true"
          >
            <path
              d="M5 13l4 4L19 7"
              pathLength={1}
              strokeDasharray={1}
              strokeDashoffset={drawn ? 0 : 1}
              className="transition-[stroke-dashoffset] duration-300 ease-out"
            />
          </svg>
          You&apos;re in
        </span>
      </div>
      <FieldMessage state={error != null ? "error" : null}>
        {error}
      </FieldMessage>
    </div>
  );
}
